head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[bigDecimal > M > divide]<br/>현재 bigDecimal 데이터를 입력받은 bigDecimal 데이터로 나누어 결과를 반환합니다.",
    "validation" : [
        "bigDecimal(필수) 파라미터로 나눗셈의 제수(나누는 수)에 해당하는 bigDecimal 데이터를 설정할 수 있어야 합니다.",
        "나눗셈 결과를 bigDecimal 타입으로 반환해야 합니다.",
        "0 으로 나누는 경우 NaN 을 나타내는 bigDecimal 을 반환해야 합니다.",
        "피연산자가 빈 문자열에서 생성된 bigDecimal 인 경우 0 으로 대체하여 연산해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_divide_onclick = function () {
    let a = $p.bigDecimal("111111111111111");
    let b = $p.bigDecimal("222222222222222");
    let ret = a.divide(b);
    wf_body_bottom.getObj("scwin").setReturnValue("a.divide(b) : " + ret.toString());
}



scwin.btn_divideZero_onclick = function () {
    let a = $p.bigDecimal("111111111111111");
    let c = $p.bigDecimal("0");
    let ret = a.divide(c);
    wf_body_bottom.getObj("scwin").setReturnValue("a.divide(0) : " + ret.toString());
}



scwin.btn_divideEmpty_onclick = function () {
    let a = $p.bigDecimal("111111111111111");
    let d = $p.bigDecimal("");
    let ret = a.divide(d);
    wf_body_bottom.getObj("scwin").setReturnValue("a.divide('') : " + ret.toString());
}
